import type {OpenAnalysisRun} from '../../../packages/ports/open-analysis-runtime.ts';
import type {MemberSourceInspection} from '../../../packages/ports/member-source.ts';
type ReportProfileFactory=typeof import('../../../profiles/personal/open-analysis.ts').createPersonalOpenAnalysisWorkspace;
const profileWithReportEdit=(factory:ReportProfileFactory,config:Parameters<ReportProfileFactory>[0])=>factory({...config,runtime:config.runtime?withReportEdit(config.runtime):undefined,createRuntime:config.createRuntime?(ledger,context)=>withReportEdit(config.createRuntime!(ledger,context)):undefined});

const source:MemberSourceInspection={version:'1.0',sources:[{source_id:randomUUID(),display_name:'选定.csv',format:'csv',sha256:createHash('sha256').update(new Uint8Array([1])).digest('hex'),byte_length:'16',sheets:[{sheet_id:randomUUID(),name:'CSV',state:'visible',rows:[{row:1,cells:[{column:'A',type:'string',value:'数量'}]},{row:2,cells:[{column:'A',type:'number',value:'7'}]},{row:3,cells:[{column:'A',type:'number',value:'3'}]}]}]}]};
function factory(){const f=Reflect.get(workspace,'createPersonalOpenAnalysisWorkspace');assert.equal(typeof f,'function','OA-S01: production workspace must connect the open task, calculation and durable outcome');return (config:any)=>profileWithReportEdit(f,config);}
function options(root:string,runtime:{run(input:OpenAnalysisRun):Promise<any>}){return {projectRoot:root,runtime,inspect:async()=>source,authorizeConfiguration:async()=>({config_sha256:'b'.repeat(64),recipients:['MiniMax-M3','mimo-v2.6-flash']})};}
function input(){return {version:'1.0',command_id:randomUUID(),question:'汇总这份资料的数量',confirmed:true,sources:[{source_id:source.sources[0]!.source_id,display_name:'选定.csv',format:'csv',bytes:new Uint8Array([1])}]};}
async function calculate(i:OpenAnalysisRun){const call=(n:string,a={})=>i.tools.find(t=>t.name===n)!.execute(a,i.signal);await call('inspect_selected');await call('set_framework',{version:'1.0',goal:'汇总数量',source_id:source.sources[0]!.source_id,sheet_id:source.sources[0]!.sheets[0]!.sheet_id,operation:'sum',column:'A',unit:'数量'} as any);await call('calculate_and_verify');return {text:'已独立核验：合计10。',tools:[]};}
test('OA-S01/RT06: normal open workspace saves exact selected data, verified value and readable history; duplicate/read does not execute',async()=>{
 const root=mkdtempSync(join(browserEvidenceRoot,'open-web-'));let calls=0;const cfg=options(root,{run:async i=>{calls++;return calculate(i);}}),app=factory()(cfg),command=input();
 try{const first=await app.submit(command);assert.equal(first.identity.task_id,command.command_id);await app.collect();const saved=app.read(command.command_id);assert.equal(saved.state,'saved');assert.ok(saved.outcome);assert.equal(saved.outcome!.calculation.value,'10');assert.equal(saved.outcome.verification.value,'10');assert.match(saved.outcome.explanation.text,/已核验事实/);assert.match(saved.outcome.explanation.text,/\[10 数量\]\(juanerai-number:F1\)/);assert.equal(saved.outcome.numeric_report!.values[0]!.value,'10');assert.match(saved.outcome.explanation.text,/分析解释/);assert.equal((await app.submit(command)).state,'saved');assert.equal(calls,1);assert.equal(app.list().length,1);await assert.rejects(()=>app.submit({...command,question:'另外的问题'}),{code:'COMMAND_CONFLICT'});const reopened=factory()(cfg);assert.equal(reopened.read(command.command_id).state,'saved');assert.equal(calls,1);await reopened.close();}finally{await app.close();}
});
