test('OA-RT04: stop during model work fences late outcome, keeps UNKNOWN until acknowledgement and never auto restarts',async()=>{
 const root=mkdtempSync(join(browserEvidenceRoot,'open-web-stop-'));let release!:()=>void;const waiting=new Promise<void>(r=>release=r);const cfg=options(root,{run:async i=>{await waiting;return calculate(i);}}),app=factory()(cfg),command=input();
 try{await app.submit(command);assert.equal(app.stop(command.command_id).state,'unknown');release();await app.collect();assert.equal(app.read(command.command_id).state,'stopped');assert.equal(app.read(command.command_id).outcome,null);const reopened=factory()(cfg);assert.equal(reopened.read(command.command_id).state,'stopped');await reopened.close();}finally{release();await app.close();}
});


