test('OA-RT04: explicitly resume a settled stopped task with saved checkpoint and unchanged configuration',async()=>{
 const root=mkdtempSync(join(browserEvidenceRoot,'open-web-resume-'));let ready!:()=>void,release!:()=>void;const began=new Promise<void>(r=>ready=r),wait=new Promise<void>(r=>release=r);let runs=0;
 const app=factory()(options(root,{run:async i=>{runs++;if(runs===1){await calculate(i);await i.saveContinuation!({version:'1.0',turn:1,messages:[{speaker:'user',text:i.prompt}]});ready();await wait;if(i.signal.aborted)throw Object.assign(Error('CANCELLED'),{code:'CANCELLED'});}else {assert.equal(i.continuation?.turn,1);return {text:'恢复后核验10',tools:[]};}return {text:'late',tools:[]};}})),command=input();
 try{assert.equal(typeof app.resume,'function');await app.submit(command);await Promise.race([began,new Promise((_,reject)=>setTimeout(()=>reject(Error('checkpoint not saved')),1500))]);app.stop(command.command_id);release();await app.collect();assert.equal(app.read(command.command_id).state,'stopped');assert.equal(typeof app.resume,'function');await app.resume(command.command_id);await app.collect();assert.equal(app.read(command.command_id).state,'saved');const saved=app.read(command.command_id);assert.ok(saved.outcome);assert.equal(saved.outcome!.calculation.value,'10');assert.equal(runs,2);}finally{release();await app.close();}
});

test('OA-S03/C03: natural follow-up keeps one task and old report; expression change reuses checked facts, duplicate revision command never repeats',async()=>{
 const root=mkdtempSync(join(browserEvidenceRoot,'open-web-revise-'));let runs=0,computations=0;
 const app=factory()(options(root,{run:async i=>{runs++;if(runs===1){computations++;await calculate(i);await i.saveContinuation!({version:'1.0',turn:1,messages:[{speaker:'user',text:i.prompt},{speaker:'assistant',text:'合计10',calls:[]}]});return {text:'合计10',tools:[]};}assert.equal(i.continuation?.messages.at(-1)?.speaker,'user');return {text:'数量总计10',tools:[]};}})),command=input();
 try{assert.equal(typeof app.revise,'function');await app.submit(command);await app.collect();const change={version:'1.0',command_id:randomUUID(),expected_revision:'1',question:'用一句话解释'};await app.revise(command.command_id,change);await app.collect();const saved=app.read(command.command_id);assert.equal(saved.identity.revision,'2');assert.ok(saved.outcome);assert.ok(saved.history);assert.ok(saved.history[0].outcome);assert.match(saved.outcome.explanation.text,/数量总计对应保存结果/);assert.match(saved.history[0].outcome.explanation.text,/合计对应保存结果/);assert.match(saved.outcome.explanation.text,/已核验事实/);assert.match(saved.history[0].outcome.explanation.text,/已核验事实/);assert.equal(saved.history[0].identity.task_id,saved.identity.task_id);await app.revise(command.command_id,change);assert.equal(runs,2);assert.equal(computations,1);await assert.rejects(()=>app.revise(command.command_id,{...change,command_id:randomUUID(),question:'新问题'}),{code:'REVISION_CONFLICT'});}finally{await app.close();}
});

