test('OA-S03/C02: confirmed material replacement remains one task, renews exact scope and recomputes; unconfirmed change has no effect',async()=>{
 const root=mkdtempSync(join(browserEvidenceRoot,'open-web-material-'));let reads=0,runs=0;
 const cfg={...options(root,{run:async i=>{runs++;const data=await i.tools.find(t=>t.name==='inspect_selected')!.execute({},i.signal) as MemberSourceInspection;await i.tools.find(t=>t.name==='set_framework')!.execute({goal:'数量',source_id:data.sources[0]!.source_id,sheet_id:data.sources[0]!.sheets[0]!.sheet_id,operation:'sum',column:'A',unit:'数量'},i.signal);await i.tools.find(t=>t.name==='calculate_and_verify')!.execute({},i.signal);return {text:'实际核验',tools:[]};}}),inspect:async ({sources}:any)=>{reads++;const copy=structuredClone(source);if(sources[0].bytes[0]===2){Reflect.set(copy.sources[0]!,'sha256',createHash('sha256').update(sources[0].bytes).digest('hex'));Reflect.set(copy.sources[0]!.sheets[0]!.rows[1]!.cells[0]!,'value','17');}return copy;}};
 const app=factory()(cfg),command=input();try{
  await app.submit(command);await app.collect();const old=app.read(command.command_id),change={version:'1.0',command_id:randomUUID(),expected_revision:'1',question:command.question,confirmed:true,sources:command.sources.map(s=>({...s,bytes:new Uint8Array([2])}))};
  await assert.rejects(()=>app.revise(command.command_id,{...change,confirmed:false}),{code:'AUTHORITY_REQUIRED'});assert.equal(reads,1);assert.equal(runs,1);
  await app.revise(command.command_id,change);await app.collect();const next=app.read(command.command_id);assert.equal(next.identity.task_id,old.identity.task_id);assert.equal(next.identity.revision,'2');assert.notEqual(next.identity.grant_id,old.identity.grant_id);assert.notEqual(next.identity.scope_sha256,old.identity.scope_sha256);assert.equal(JSON.stringify(next.checkpoint).includes(old.identity.scope_sha256),false,'old scope material/edit input must not be resent; current edit may have its own messages');assert.equal(JSON.stringify(next.checkpoint).includes(old.identity.grant_id),false,'old grant does not flow into current report editing');assert.ok(next.outcome);assert.ok(next.history);assert.ok(next.history[0]!.outcome);assert.equal(next.outcome!.calculation.value,'20');assert.equal(next.history[0]!.outcome!.calculation.value,'10');assert.deepEqual(next.history[0]!.outcome!.numeric_report,old.outcome!.numeric_report);assert.equal(next.outcome!.numeric_report!.identity.revision,'2');assert.notEqual(next.outcome!.numeric_report!.report_sha256,old.outcome!.numeric_report!.report_sha256);assert.equal(next.outcome!.numeric_report!.values[0]!.value,'20');assert.equal(next.outcome!.numeric_report!.values[0]!.source_sha256,next.identity.scope_sha256);
  await app.revise(command.command_id,change);assert.equal(reads,2);assert.equal(runs,2);
  await assert.rejects(()=>app.revise(command.command_id,{...change,sources:command.sources}),{code:'COMMAND_CONFLICT'});
 }finally{await app.close();}
});


