 const cfg=options(root,{run:async i=>{calls++;if(!i.tools.some(t=>t.name==='calculate_and_verify')){assert.equal(i.tools.some(t=>t.name==='calculate_and_verify'),false);await i.tools.find(t=>t.name==='set_framework')!.execute({goal:'平均数量',source_id:source.sources[0]!.source_id,sheet_id:source.sources[0]!.sheets[0]!.sheet_id,operation:'mean',column:'A',unit:'数量',group_mode:'none'},i.signal);return {text:'由总数量改为平均数量，旧结论不作为新版答案。',tools:[]};}return calculate(i);}});
