 const runtime={run:async(i:OpenAnalysisRun)=>{runs++;const call=(n:string,a={})=>{const t=i.tools.find(t=>t.name===n);assert.ok(t);return t.execute(a,i.signal);};if(runs===1){await call('assess_meaning',{definitions:[],conflicts:[{dimension:'metric',question:'数量还是销售额？',alternatives:['数量','销售额'],resolution_quote:null}]} as any);await call('ask_user',{text:'数量还是销售额？'} as any);return {text:'请明确指标',tools:[]};}await call('assess_meaning',{definitions:[{dimension:'metric',value:'数量',user_quote:'本次使用数量'}],conflicts:[{dimension:'metric',question:'数量还是销售额？',alternatives:['数量','销售额'],resolution_quote:'本次使用数量'}]} as any);return calculate(i);}};
