test('FM-A02/03: declared steps execute their actual IR, block dependencies until qualified and save each independently',async()=>{
 const root=mkdtempSync(join(browserEvidenceRoot,'open-executable-steps-'));const a=randomUUID(),b=randomUUID();let observed:any;
 const app=factory()(options(root,{run:async i=>{const call=(name:string,args:any={})=>{const tool=i.tools.find(t=>t.name===name);assert.ok(tool,'declared step plan must have a production consumer');return tool.execute(args,i.signal) as Promise<any>;};const data=await call('inspect_selected') as MemberSourceInspection,plan={version:'1.0',goal:'核对数量',source_id:data.sources[0]!.source_id,sheet_id:data.sources[0]!.sheets[0]!.sheet_id,operation:'sum',column:'A',unit:'件'},step=(id:string,depends_on:string[],p:any)=>({step_id:id,title:p.operation==='mean'?'核对平均数量':'核对总数量',depends_on,hypotheses:['不能证明业务原因'],required_evidence:['实际数量字段'],limitations:['算术范围'],plan:p});await call('set_analysis_steps',{version:'1.0',steps:[step(a,[],plan),step(b,[a],{...plan,operation:'mean',version:'1.1',group_by:null,filters:[]})]});const blocked=await call('execute_step',{step_id:b});assert.equal(blocked.status,'blocked');assert.equal(blocked.calculation_performed,false);await call('set_framework',{...plan,operation:'mean',version:'1.1',group_by:null,filters:[]});const bypass=await call('calculate_and_verify');assert.equal(bypass.status,'blocked');assert.equal(bypass.calculation_performed,false);const first=await call('execute_step',{step_id:a});assert.equal(first.calculation.value,'10');const second=await call('execute_step',{step_id:b});assert.equal(second.calculation.value,'5');observed=[first,second];return {text:'本轮总数量10、平均5，均已核验；原因未证实。',tools:[]};}}));const command=input();try{await app.submit(command);await app.collect();const t=app.read(command.command_id);assert.equal(t.state,'saved');assert.ok(t.framework?.steps);assert.ok(t.verified_steps);assert.equal(t.framework.steps.steps.length,2);assert.equal(t.verified_steps.length,2);assert.deepEqual(t.verified_steps.map((s:any)=>s.calculation.value),['10','5']);assert.ok(observed);const reopened=factory()(options(root,{run:async()=>assert.fail('reopen must not execute')}));assert.equal(reopened.read(command.command_id).verified_steps?.length,2);await reopened.close();}finally{await app.close();}
});

test('FM-A03: unsupported refund branch blocks its descendants but keeps independently checked gross amount without final success',async()=>{
 const root=mkdtempSync(join(browserEvidenceRoot,'open-steps-partial-')),a=randomUUID(),b=randomUUID(),c=randomUUID();let attempted=0;
 const app=factory()(options(root,{run:async i=>{const call=(n:string,x:any={})=>i.tools.find(t=>t.name===n)!.execute(x,i.signal) as Promise<any>;const data=await call('inspect_selected') as MemberSourceInspection,plan={version:'1.0',goal:'订单总额',source_id:data.sources[0]!.source_id,sheet_id:data.sources[0]!.sheets[0]!.sheet_id,operation:'sum',column:'A',unit:'元'},step=(id:string,deps:string[],p:any)=>({step_id:id,title:p.goal,depends_on:deps,hypotheses:[],required_evidence:['本轮订单与退款'],limitations:['净额尚未核验'],plan:p});await call('set_analysis_steps',{version:'1.0',steps:[step(a,[],plan),step(b,[],{...plan,goal:'关联退款',operation:'refund_join'}),step(c,[a,b],{...plan,goal:'净销售额'})]});assert.equal((await call('execute_step',{step_id:a})).calculation.value,'10');assert.equal((await call('execute_step',{step_id:b})).status,'unsupported');const held=await call('execute_step',{step_id:c});assert.equal(held.status,'blocked');assert.equal(held.calculation_performed,false);attempted++;await call('ask_user',{text:'订单总额已核验。退款关联方法尚未支持，净额未计算；请补充可核对的净额来源。'});return {text:'等待补充',tools:[]};}}));const command=input();try{await app.submit(command);await app.collect();const t=app.read(command.command_id);assert.equal(t.state,'waiting');assert.equal(t.outcome,null);assert.equal(t.verified_steps?.length,1);assert.equal(t.verified_steps![0]!.framework.plan.goal,'订单总额');assert.equal(t.verified_steps![0]!.calculation.value,'10');assert.equal(attempted,1);}finally{await app.close();}
});

test('FM-A03/FM-X: explicit branch cancellation creates exact smaller scope, preserves old partials and recomputes retained facts',async()=>{
 const root=mkdtempSync(join(browserEvidenceRoot,'open-step-cancel-')),a=randomUUID(),b=randomUUID(),c=randomUUID();let runs=0;
 const app=factory()(options(root,{run:async i=>{runs++;const call=(n:string,x:any={})=>i.tools.find(t=>t.name===n)!.execute(x,i.signal) as Promise<any>;if(runs===1){const data=await call('inspect_selected') as MemberSourceInspection,plan={version:'1.0',goal:'订单总额',source_id:data.sources[0]!.source_id,sheet_id:data.sources[0]!.sheets[0]!.sheet_id,operation:'sum',column:'A',unit:'元'},step=(id:string,deps:string[],p:any)=>({step_id:id,title:p.goal,depends_on:deps,hypotheses:[],required_evidence:['订单与退款'],limitations:['不是优惠券决策'],plan:p});await call('set_analysis_steps',{version:'1.0',steps:[step(a,[],plan),step(b,[],{...plan,goal:'退款关联',operation:'refund_join'}),step(c,[a,b],{...plan,goal:'净销售额'})]});await call('execute_step',{step_id:a});await call('ask_user',{text:'退款关联未支持，净额未计算。'});return {text:'等待',tools:[]};}assert.match(i.prompt,/取消退款关联/);const fact=await call('execute_step',{step_id:a});assert.equal(fact.calculation.value,'10');return {text:'仅完成订单总额核对；原净额与优惠券问题未完成。',tools:[]};}}));const command=input();try{await app.submit(command);await app.collect();assert.equal(app.read(command.command_id).state,'waiting');const cancel={version:'1.0',command_id:randomUUID(),expected_revision:'1',step_id:b,reason:'先只保留订单总额，退款规则后续补充',confirmed:true};await app.cancelStep(command.command_id,cancel);await app.collect();const t=app.read(command.command_id);assert.equal(t.state,'saved');assert.equal(t.identity.revision,'2');assert.equal(t.framework?.steps?.steps.length,1);assert.equal(t.framework?.steps?.steps[0]?.step_id,a);assert.equal(t.history?.[0]?.verified_steps?.[0]?.calculation.value,'10');assert.equal(t.verified_steps?.[0]?.calculation.value,'10');assert.notEqual(t.verified_steps?.[0]?.identity.run_id,t.history?.[0]?.verified_steps?.[0]?.identity.run_id);const count=runs;await app.cancelStep(command.command_id,cancel);assert.equal(runs,count);await assert.rejects(()=>app.cancelStep(command.command_id,{...cancel,reason:'另一个理由'}),{code:'COMMAND_CONFLICT'});}finally{await app.close();}
});

