test('V13-AC133: trusted workspace proves an interrupted step only before persisted calculation admission',async()=>{
 const {createLocalOpenAnalysisStore}=await import('../../../adapters/storage-local/open-analysis.ts'),workspaceModule=await import('../../../packages/application/open-analysis-workspace.ts');
 const root=mkdtempSync(join(browserEvidenceRoot,'precalculation-proof-')),store=createLocalOpenAnalysisStore({projectRoot:root});let ready!:()=>void,release!:()=>void;const admitted=new Promise<void>(r=>ready=r),wait=new Promise<void>(r=>release=r);const step_id=randomUUID(),command=input();
 const app=factory()(options(root,{run:async i=>{const call=(name:string,args:any={})=>i.tools.find(t=>t.name===name)!.execute(args,i.signal),data:any=await call('inspect_selected');await call('set_analysis_steps',{version:'1.0',steps:[{step_id,title:'数量合计',depends_on:[],hypotheses:[],required_evidence:['真实数量'],limitations:[],plan:{version:'1.0',goal:'数量合计',source_id:data.sources[0].source_id,sheet_id:data.sources[0].sheets[0].sheet_id,operation:'sum',column:'A',unit:'件'}}]});ready();await wait;return {text:'未计算',tools:[]};}}));
 try{
  await app.submit(command);await admitted;store.recover(command.command_id);const current=store.read(command.command_id)!;
  const prove:(...args:any[])=>any=Reflect.get(workspaceModule,'interruptedStepPreExecutionProof');assert.equal(typeof prove,'function','Application must prove the pre-calculation boundary, not the Adapter assume absent results');
  const proof=prove(current,current.identity,step_id);assert.ok(proof);assert.equal(proof.task_sha256,taskHash(current));assert.equal(prove({...current,state:'running'},current.identity,step_id),null);assert.equal(prove(current,{...current.identity,revision:'2'},step_id),null);assert.equal(prove(current,current.identity,randomUUID()),null);
  assert.equal(prove({...current,step_events:[{phase:'running',step_id}]},current.identity,step_id),null,'a started calculation cannot be disposed');assert.equal(prove({...current,verified_steps:[{}]},current.identity,step_id),null);assert.equal(prove({...current,explorations:[{}]},current.identity,step_id),null);assert.equal(prove({...current,framework:{...current.framework,steps:null}},current.identity,step_id),null);
  assert.equal(store.read(command.command_id)!.state,'unknown');
 }finally{release();await app.collect();await app.close();}
});

